async function invokeInstalledDefinitionCall(
  acquisitionKind: InstalledDefinitionCallTransportResult["acquisitionKind"],
  call: AnyDefinitionCall,
): Promise<InstalledDefinitionCallTransportOutcome> {
  const selected = selectedCallable(call, acquisitionKind);
  if ("kind" in selected) return selected;
  const receipt = await runExactDefinition(
    call,
    selected.callable(call),
  );
  // The native fixed owner admits the complete call before its effects. Some
  // direct owners first reject resource structure, while Product's authority
  // wrapper reports its call check as a resource relation fault. Only those
  // ambiguous admission failures need the compatibility check. Execution
  // faults and successful progression retain their actual owner receipt.
  const fault = receipt.failure?.fault;
  const ambiguousAdmission = fault?.stage === "resource_admission" && (
    fault.code === "invalid_resource_assertion" ||
    fault.code === "resource_relation_mismatch" &&
      fault.message === "TypeError: definition call differs from its fixed owner"
  );
  if (acquisitionKind === "acquired" && (
    fault?.code === "call_identity_mismatch" ||
    ambiguousAdmission && admitExactDefinitionCall(call, selected.declaration) === null
  )) {
    return refusal(
      "invalid_definition_call",
      "DefinitionCall differs from its exact installed invocation contract",
    );
  }
  return Object.freeze({
    kind: "installed_definition_call_transport_result" as const,
    schemaVersion: "5.0.0" as const,
    acquisitionKind,
    receipt,
  });
}

import { HELLO_WORLD_IDS } from "../gtl/hello_world.js";
import {
  ABI5_PACKAGE_NAME,
  ABI5_PACKAGE_VERSION,
} from "../product/contracts.js";
import { sha256Canonical } from "../shared/digests.js";
import { deepFreeze } from "../shared/immutable.js";
import type {
  HelloWorldLeafRealizationCandidate,
} from "./contracts.js";
import type { HelloWorldInput } from "../gtl/contracts.js";
import type { PackagedLeafImplementationDescriptor } from "../product/implementation_resolution.js";

const descriptorBody = {
  implementationRef: HELLO_WORLD_IDS.implementationRef,
  packageName: ABI5_PACKAGE_NAME,
  packageVersion: ABI5_PACKAGE_VERSION,
  modulePath: "build/code/src/implementation/hello_world.js",
  namedSymbol: "realizeHelloWorld",
  computeRegime: "F_D" as const,
  inputContractRef: HELLO_WORLD_IDS.inputContractRef,
  outputContractRef: HELLO_WORLD_IDS.outputContractRef,
  failureContractRef: HELLO_WORLD_IDS.failureContractRef,
  refusalContractRef: HELLO_WORLD_IDS.refusalContractRef,
};

export const HELLO_WORLD_IMPLEMENTATION_DESCRIPTOR = deepFreeze({
  kind: "packaged_leaf_implementation_descriptor" as const,
  schemaVersion: "5.0.0" as const,
  descriptorDigest: sha256Canonical(descriptorBody),
  ...descriptorBody,
}) as PackagedLeafImplementationDescriptor;

export function realizeHelloWorld(
  input: Readonly<HelloWorldInput>,
): Readonly<HelloWorldLeafRealizationCandidate> {
  const resultCandidate = deepFreeze({
    kind: "hello_world_output" as const,
    schemaVersion: "5.0.0" as const,
    message: `Hello ${input.subject}`,
  });
  return deepFreeze({
    kind: "leaf_realization_candidate" as const,
    schemaVersion: "5.0.0" as const,
    disposition: "success" as const,
    evidenceCandidates: [{
      kind: "deterministic_evidence_candidate" as const,
      schemaVersion: "5.0.0" as const,
      implementationRef: HELLO_WORLD_IDS.implementationRef,
      inputDigest: sha256Canonical(input),
      outputDigest: sha256Canonical(resultCandidate),
    }] as const,
    resultCandidate,
  });
}

export async function constructAdmittedLeafInvocationPort(authority: {
  readonly historicalSource?: AbgHistoricalGraphCallSourceResource;
  readonly prefix: ValidatedRuntimeEventPrefix;
  readonly artifactTruth: ExactPrefixArtifactTruthProjection;
  readonly implementationSet: AdmittedImplementationSet;
  readonly executionResolution: LoadedLeafExecutionAuthority;
  readonly semanticsProjection: InstalledLeafSemanticsProjection;
  readonly graphFunctionRef?: string;
}): Promise<LeafInvocationPort> {
  const inspected = inspectProductLeafSemanticsProjection(
    authority.semanticsProjection,
  );
  const selectedGraphFunctionRef = authority.graphFunctionRef ??
    authority.executionResolution.declarationClosure.selectedGraphFunctionRef;
  const semanticsOwner = graphFunctionSemanticsOwner(authority.executionResolution.declarationClosure, selectedGraphFunctionRef, coordinate => exactOwnerBinding(authority.executionResolution, coordinate));
  if (semanticsOwner === null) throw new TypeError("leaf semantics lacks its declared GraphFunction owner");
  const semanticsBinding = exactOwnerBinding(
    authority.executionResolution,
    semanticsOwner,
  );
  const everyOwnerIsAdmitted = authority.executionResolution.ownerInstalls
    .every((install) =>
      hasAdmittedProductInstall(authority.artifactTruth, install)
    );
  if (
    inspected === null ||
    semanticsBinding === null ||
    !everyOwnerIsAdmitted ||
    !hasAdmittedImplementationSetAtPrefix(
      authority.prefix,
      authority.implementationSet,
    ) ||
    inspected.projection.installId !== semanticsBinding.install.installId ||
    inspected.projection.productContentDigest !==
      semanticsBinding.install.productContentDigest ||
    inspected.projection.manifestDigest !==
      semanticsBinding.install.manifestDigest ||
    inspected.projection.publicationDigest !==
      semanticsOwner.publicationDigest ||
    inspected.projection.bindingRef !== semanticsOwner.declarationRef ||
    inspected.projection.packageName !==
      semanticsBinding.install.packageName ||
    inspected.projection.packageVersion !==
      semanticsBinding.install.packageVersion ||
    !(await inspected.runtime.verifyInstalledContent())
  ) {
    throw new TypeError(
      "leaf invocation port requires the exact owner-selected admitted execution closure",
    );
  }
  const semantics = inspected.runtime;
  const modules = new Map<string, Promise<Record<string, unknown>>>();

  function uniqueContractByRef(contractRef: string) {
    const ownerMatches = authority.executionResolution.declarationClosure
      .contractOwners.filter((owner) => owner.declarationRef === contractRef);
    if (ownerMatches.length !== 1) return null;

export function executeGraphTraversalEffect(
  input: ExecuteGraphTraversalRequest,
): Effect.Effect<ExecuteGraphTraversalResult, never> {
  return Effect.catchAll(
    traversalProgram(input),
    (failure) => Effect.succeed(projectGraphTraversalFailure(failure)),
  ).pipe(Effect.map(result => {
    if (!("successorPrefix" in result)) return result;
    const current = "current" in input ? input.current : input;
    const successorPrefix = admitPendingConstructionIntentContinuation(current.store, result.successorPrefix,
      current.openedTraversalScope.runId, current.eventTime, `${current.correlationId}/pending-construction`);
    return successorPrefix === result.successorPrefix ? result : Object.freeze({ ...result, successorPrefix });
  }));
}

export async function executeGraphTraversal(
  input: ExecuteGraphTraversalRequest,
): Promise<ExecuteGraphTraversalResult> {
  const exit = await runEffectProgram(executeGraphTraversalEffect(input));
  if (Exit.isSuccess(exit)) return exit.value;
  const defect = Cause.dieOption(exit.cause);
  if (Option.isSome(defect)) throw defect.value;
  throw exit.cause;
}
